class SBTS24R2(SBTS24R1):

    def __init__(self,
                 api_client=None
                 ):
        """
        :param api_client: instance of an AdminApi class
        """
        super(SBTS24R2, self).__init__(api_client)

    def rat_reset(self, rat_type, timeout=60, graceful_cell_shutdown=None, reset_type=None):
        """
        Preform RAT reset procedure.

        :param str rat_type: RAT name, one of: ["NR", "LTE", "WCDMA", "GSM"]
        :param int timeout: Timeout for the operation.
        :param bool graceful_cell_shutdown: (Optional) - Defaults to False.
        :param str reset_type: ["Soft"|"Hard"] <optional, default value is Soft>. NF-CB008880
        :return list: RAT reset status
            For example:
                [{'id': '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-1'},
                {'confirmationNode': {'distName': '/MRBTS-1/RAT-1/URI-1/SESSION-1/RESET_IND-1/ACK-1',
                'parameters': {}}, 'indicationDistName': '/MRBTS-1/RAT-1/URI-1/SESSION-1/RESET_IND-1', '
                resultNode': {'distName': '/MRBTS-1/RAT-1/URI-1/SESSION-1/RESET_IND-1/RESULT-1',
                'parameters': {'status': 'Succeeded'}}}]

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-ratReset.html
        """
        parameters = {"type": rat_type}

        if graceful_cell_shutdown is not None:
            parameters['gracefulCellShutdown'] = graceful_cell_shutdown

        if reset_type:
            if reset_type not in ["Soft", "Hard"]:
                raise_value_error(param="reset_type",
                                  value=str(reset_type),
                                  subpage="tutorial-ratReset.html")
            parameters["resetType"] = reset_type

        response = self._api_client.execute_procedure("ratReset", parameters, timeout)
        if response is None:
            raise DataNotAvailable("RAT reset status has not been provided by M-Plane.")
        return response

    def configure_cplane_traces(self, dscp, timeout=60, detailed_output=False):
        """
        Configure Cplane traces.

        :param int dscp: (mandatory) <0 to 15>
        :param int timeout: Timeout for the operation, 60 second by default.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/hashes/master-6308205-9a57cc879147d86f2e35225b54572b08ee80f6d9/cli-docs/tutorial-configureCPlaneTraces.html
        """
        parameters = {"configurationParameters": {"dscp": dscp}}
        response = self._api_client.execute_customer_procedure("configureCPlaneTraces", parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

