    def configure_snapshot(self, destination, max_trigger_number, upload_delay_6450, destination_6450,  # noqa: C901
                           activate_default_triggers, lss_ipaddress=None, lss_port_number=None, lss_directory=None,
                           fault_snapshot_triggers=None, timeout=60):
        """
        Configure snapshot.

        :param string destination: Diagnostic snapshot destination. One of ["netact"|"lss"|"externalHTTPSServer"].
        :param int max_trigger_number: Maximum number of snapshots by fault triggers per day. [1, 200].
        :param int upload_delay_6450: Snapshot upload delay for fault 6450 [0, 24].
        :param string destination_6450: Snapshot upload destination for fault 6450 One of ["netact"|"lss"|"disabled"].
        :param bool activate_default_triggers: Activate default fault snapshot triggers.
        :param string lss_ipaddress: Optional, LSS ip address.
        :param int lss_port_number: Optional, LSS port number [1, 65535]
        :param string lss_directory: Optional, LSS directory.
        :param list fault_snapshot_triggers: Optional. Array of dictionaries containing information about faults that will
            trigger the snapshot, i.e.:
                "faultSnapshotTriggers": [{
                    "faultNumber": 1111,
                    "triggerType": "onFaultDetection" ,
                    "snapshotCoverageLevel": "Full",
                    "snapshotFilterKeywords": "xxx"
                }]
        :param int timeout: Time in seconds to wait for positive procedure result.
        :return dict: Procedure feedback.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-sendSnapshotConfiguration.html
        """
        if destination not in ["netact", "lss", "externalHTTPSServer"]:
            raise_value_error(param="destination",
                              value=str(destination),
                              subpage="tutorial-sendSnapshotConfiguration.html")

        if destination_6450 not in ["netact", "lss", "disabled"]:
            raise_value_error(param="destination_6450",
                              value=str(destination_6450),
                              subpage="tutorial-sendSnapshotConfiguration.html")

        parameters = {"diagSnapDestination": destination,
                      "maxNumSnapByFaultTrigPerDay": max_trigger_number,
                      "snapshotUploadDelayForFault6450": upload_delay_6450,
                      "snapshotUploadDestinationForFault6450": destination_6450,
                      "actDefaultFaultSnapTriggers": activate_default_triggers}

        if lss_ipaddress or lss_port_number or lss_directory:
            lss_config = {"lssIPaddress": lss_ipaddress,
                          "lssPortNo": lss_port_number,
                          "directory": lss_directory}
            lss_config = {key: value for key, value in lss_config.items() if value is not None}
            parameters["lssConfig"] = lss_config

        if fault_snapshot_triggers:
            parameters["faultSnapshotTriggers"] = fault_snapshot_triggers

        return self._api_client.execute_procedure("sendSnapshotConfiguration", parameters, timeout)

    def update_software(self, sw_package, should_activate=True, timeout=600, should_reset_radios=False, override_ru_software=None,
                        independent_sw_update_type=None):
        """
        Perform software update.

        :param string sw_package: Path to software package. URLs are also supported, it will automatically download and
        update the software then.
        :param boolean should_activate: Activate software flag.
        :param boolean should_reset_radios: Activate reset radios flag.
        :param int timeout: Time to wait for positive procedure result.
        :param boolean override_ru_software: Optional, default: false (since CB010779-A and CB012267
        :param string independent_sw_update_type: Optional, ["RuSwOnly"|"All"] (since CB010780, "All" is default)
        :raise DataNotAvailable: Raised if operation is invalid from Node-B side.
        :return str: Status of the operation. Possible statuses: 'Accepted' or 'Failed'.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-softwareUpdate.html
        """
        parameters = {"shouldActivate": should_activate,
                      "shouldResetRadios": should_reset_radios,
                      "inputFileName": sw_package}

        if override_ru_software:
            parameters["overrideIndependentRUSW"] = override_ru_software

        if independent_sw_update_type:
            parameters["independentSwUpgradeType"] = independent_sw_update_type

        if sw_package.lower().startswith('http'):
            response = self._api_client.execute_procedure("softwareUpdate", parameters, timeout,
                                                          input_file_url=sw_package)
        else:
            response = self._api_client.execute_procedure("softwareUpdate", parameters, timeout,
                                                          input_file_name=sw_package)

        if response is None:
            raise DataNotAvailable("Operation is invalid from Node-B side")

        return response

    def start_rf_scanning_test(self, technology, radio_dn, capture_type, output_file_name, antenna_dn=None,
                               antenna_panel=None, cell_dn=None,
                               timeout=60, detailed_output=False):
        """
        Start RF scanning test.

        :param string technology: Mandatory, ["WCDMA", "LTE_FDD", "LTE_TDD", "NR_FDD", "NR_TDD"],
         "WCDMA", "LTE_TDD", "NR_TDD" is supported only in R&D mode)
        :param string radio_dn: Mandatory, RMOD_R runtime DN
        :param string capture_type: Mandatory, ["TX_FEEDBACK" | "RX_COMBINED" | "RX_COMBINED_RAW" | "RX_CARRIER"],
         "TX_FEEDBACK" is supported only in R&D mode.
        :param string output_file_name: Mandatory, path to the output .zip file.
        :param string antenna_dn: Optional, ANTL_R runtime DN, Optional,it is not required for mMIMO TDD radio or start a radio level RF Scan.
        :param string antenna_panel: Optional, ["PHYANT_1_Full_Array" | "PHYANT_1_Top_Array" | "PHYANT_1_Bottom_Array" |
         "PHYANT_1_Left_Array" | "PHYANT_1_Right_Array" | "PHYANT_1_All_Arrays"]; only required for TDD mMIMO radio.
        :param string cell_dn: Optional, NRCELL DN/LNCEL DN/WNCEL DN; only required if "captureType"="RX_CARRIER"
        :param int timeout: Time to wait for positive procedure result.
        :param bool detailed_output: return full request response when True, by default set to False.
        :return str: Status of the operation. Possible statuses: 'Accepted' or 'Failed'.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-startRFScanningTest.html
        """
        parameters = {"technology": technology,
                      "radioDN": radio_dn,
                      "captureType": capture_type}

        if antenna_dn:
            parameters["antennaDN"] = antenna_dn
        if antenna_panel:
            parameters["antennaPanel"] = antenna_panel
        if cell_dn:
            parameters["cellDN"] = cell_dn

        response = self._api_client.execute_customer_procedure("startRFScanningTest", parameters, timeout,
                                                               output_file_name=output_file_name)
        return response if detailed_output else response.get(self._provided_content.request_message)
